import com.jayway.jsonpath.JsonPath
import com.optarena.inventory.repository.ItemRepository
import com.optarena.inventory.repository.WarehouseRepository
import org.hamcrest.Matchers.`is`
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc
import org.springframework.boot.test.context.SpringBootTest
import org.springframework.http.MediaType
import org.springframework.test.web.servlet.MockMvc
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post
import org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath
import org.springframework.test.web.servlet.result.MockMvcResultMatchers.status

@SpringBootTest
@AutoConfigureMockMvc
class WarehouseCapacityTest {

    @Autowired
    private lateinit var mockMvc: MockMvc

    @Autowired
    private lateinit var warehouseRepository: WarehouseRepository

    @Autowired
    private lateinit var itemRepository: ItemRepository

    @BeforeEach
    fun resetState() {
        warehouseRepository.clear()
        itemRepository.clear()
    }

    @Test
    fun itemCreationRejectedWhenExceedingCapacity() {
        val wBody = mockMvc.perform(
            post("/api/warehouses").contentType(MediaType.APPLICATION_JSON)
                .content("""{"name":"W","location":"x","maxCapacity":10}""")
        ).andReturn().response.contentAsString
        val warehouseId: Int = JsonPath.read(wBody, "$.id")

        mockMvc.perform(
            post("/api/items").contentType(MediaType.APPLICATION_JSON)
                .content("""{"sku":"A","name":"A","warehouseId":$warehouseId,"quantity":6,"reorderThreshold":0}""")
        ).andExpect(status().isCreated)

        mockMvc.perform(
            post("/api/items").contentType(MediaType.APPLICATION_JSON)
                .content("""{"sku":"B","name":"B","warehouseId":$warehouseId,"quantity":5,"reorderThreshold":0}""")
        ).andExpect(status().isBadRequest)
    }

    @Test
    fun inMovementRejectedWhenExceedingCapacity() {
        val wBody = mockMvc.perform(
            post("/api/warehouses").contentType(MediaType.APPLICATION_JSON)
                .content("""{"name":"W","location":"x","maxCapacity":10}""")
        ).andReturn().response.contentAsString
        val warehouseId: Int = JsonPath.read(wBody, "$.id")

        val iBody = mockMvc.perform(
            post("/api/items").contentType(MediaType.APPLICATION_JSON)
                .content("""{"sku":"A","name":"A","warehouseId":$warehouseId,"quantity":8,"reorderThreshold":0}""")
        ).andReturn().response.contentAsString
        val itemId: Int = JsonPath.read(iBody, "$.id")

        mockMvc.perform(
            post("/api/items/$itemId/movements").contentType(MediaType.APPLICATION_JSON)
                .content("""{"type":"IN","quantity":5}""")
        ).andExpect(status().isBadRequest)

        mockMvc.perform(
            post("/api/items/$itemId/movements").contentType(MediaType.APPLICATION_JSON)
                .content("""{"type":"IN","quantity":2}""")
        )
            .andExpect(status().isCreated)
            .andExpect(jsonPath("$.item.quantity", `is`(10)))
    }
}

